public IList<int> DistanceK(TreeNode root, TreeNode target, int k)
{
    var parent = new Dictionary<TreeNode, TreeNode?>();
    BuildParent(root, null, parent);
    var queue = new Queue<TreeNode?>();
    queue.Enqueue(target);
    var visited = new HashSet<TreeNode> { target };
    int dist = 0;
    while (queue.Count > 0)
    {
        int size = queue.Count;
        if (dist == k) return queue.Where(n => n != null).Select(n => n.Val).Cast<int>().ToList();
        for (int i = 0; i < size; i++)
        {
            TreeNode? node = queue.Dequeue();
            if (node == null) continue;
            foreach (var neighbor in new TreeNode?[] { node.Left, node.Right, parent.GetValueOrDefault(node) })
            {
                if (neighbor != null && visited.Add(neighbor))
                    queue.Enqueue(neighbor);
            }
        }
        dist++;
    }
    return new List<int>();
}

private void BuildParent(TreeNode? node, TreeNode? p, Dictionary<TreeNode, TreeNode?> parent)
{
    if (node == null) return;
    parent[node] = p;
    BuildParent(node.Left, node, parent);
    BuildParent(node.Right, node, parent);
}
